    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    result = []
    has_letter = False

    for ch in s:
        if ch.isalpha():
            result.append(ch.swapcase())
            has_letter = True
        else:
            result.append(ch)

